import sys

def stringConversion(X: str, Y: str) -> int:
    n = len(X)
    m = len(Y)

    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        dp[i][0] = False

    for j in range(1, m + 1):
        dp[0][j] = False

    for i in range(1, n + 1):

        x_char = X[i - 1]

        if x_char.islower():
            for j in range(1, m + 1):
                y_char = Y[j - 1]

                if x_char.upper() == y_char:
                    if dp[i - 1][j - 1]:
                        dp[i][j] = True

                if dp[i - 1][j]:
                    dp[i][j] = True
        else:

            for j in range(1, m + 1):
                if x_char == Y[j - 1]:
                    if dp[i - 1][j - 1]:

                        if dp[i - 1][j]:
                            dp[i][j] = True
                else:
                    if dp[i - 1][j]:
                        dp[i][j] = True

    return 1 if dp[n][m] else 0

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) >= 2:
        X = lines[0].strip()
        Y = lines[1].strip()
        result = stringConversion(X, Y)
        print(result)

if __name__ == "__main__":
    main()
